			return 1;
		long p = power(a, k >> 1);
		p = p * p % MD;
		if ((k & 1) == 1)
			p = p * a % MD;
		return p;
	}
	long ch(int n, int k) {
		return (long) ff[n] * gg[k] % MD * gg[n - k] % MD;
	}
	void main() {
		int n = sc.nextInt();
		long k_ = sc.nextLong();
		if (k_ >= n) {
			println(0);
			return;
		}
		int c = n - (int) k_;
		ff = new int[n + n];
		gg = new int[n + n];
		for (int f = 1, i = 0; i < n + n; i++) {
			gg[i] = (int) power(ff[i] = f, MD - 2);
			f = (int) ((long) f * (i + 1) % MD);
		}
		long ans = 0;
		for (int a = 1; a <= c; a++) {
